namespace ghidra.app.plugin.core.symtable;




using docking.widgets.table;
using docking.widgets.table.threaded;
using ghidra.program.model.symbol;
using ghidra.util.table;
using ghidra.util.task;

/**
 * A class to enable drag and drop for temporary symbol tables.
 */
public class TransientSymbolTableDnDAdapter : SymbolTableDnDAdapter {

	private TransientSymbolTableModel model;

	public TransientSymbolTableDnDAdapter(GhidraTable table, TransientSymbolTableModel model) : base(table, model)
    {
		this.model = model;
	}

	/* @Override */
	protected void addSymbols(List<Symbol> symbols) {

		List<SymbolRowObject> rowObjects = new();
		foreach (Symbol s in symbols) {
			rowObjects.add(new SymbolRowObject(s));
		}

		model.addInitialLoadListener(new _Anon_ThreadedTableModelListenerAdapter_1());

		TaskLauncher.launchModal("Copying Symbols", () => model.addSymbols(rowObjects));
	}

	internal class _Anon_ThreadedTableModelListenerAdapter_1 : ThreadedTableModelListenerAdapter
	{

			/* @Override */
			public void loadingFinished(bool wasCancelled) {
				TableUtils.setSelectedItems(table, rowObjects);
			}
		
	}

}
